import{_ as a,o as t,c as o,a5 as r}from"./chunks/framework.UjrY2eRK.js";const u=JSON.parse('{"title":"Choose a deployment","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/index.md","filePath":"getting-started/index.md","lastUpdated":1788123021000}'),n={name:"getting-started/index.md"};function i(l,e,d,s,h,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="choose-a-deployment" tabindex="-1">Choose a deployment <a class="header-anchor" href="#choose-a-deployment" aria-label="Permalink to &quot;Choose a deployment&quot;">​</a></h1><p>Trinity Push Gateway is operated for one pair of Android and iOS application IDs. Before deploying it, create a Firebase project, register both applications, enable the FCM HTTP v1 API, and create a dedicated service account that may send messages for that project.</p><h2 id="cloudflare-workers" tabindex="-1">Cloudflare Workers <a class="header-anchor" href="#cloudflare-workers" aria-label="Permalink to &quot;Cloudflare Workers&quot;">​</a></h2><p>Choose Cloudflare when you want the smallest operational footprint. The Worker uses D1 for delivery coordination, a Cloudflare rate-limit binding, and a daily cleanup trigger. The default limits are designed to stay within a small single-tenant deployment envelope.</p><p><a href="/trinity-push-gateway/next/deployment/cloudflare/">Deploy on Cloudflare</a></p><h2 id="docker-and-bun" tabindex="-1">Docker and Bun <a class="header-anchor" href="#docker-and-bun" aria-label="Permalink to &quot;Docker and Bun&quot;">​</a></h2><p>Choose self-hosting when you need to own the runtime and data location. The supported topology is one Linux container, one SQLite database on local durable storage, and an external TLS reverse proxy.</p><p><a href="/trinity-push-gateway/next/deployment/self-hosting/">Self-host with Docker</a></p><h2 id="shared-requirements" tabindex="-1">Shared requirements <a class="header-anchor" href="#shared-requirements" aria-label="Permalink to &quot;Shared requirements&quot;">​</a></h2><ul><li>A stable HTTPS hostname reachable by Matrix homeservers.</li><li>Firebase credentials owned and rotated by the gateway operator.</li><li>Distinct Android and iOS app IDs.</li><li>A separately generated fingerprint key of at least 32 bytes.</li><li>A compatible mobile client configured in a separate client-development task.</li></ul><p>After deployment, require <code>/health</code> to return an <code>ok</code> status before registering the gateway URL with a Matrix pusher.</p>',11)])])}const m=a(n,[["render",i]]);export{u as __pageData,m as default};
